<?php $draft=$campaign['draft']; ?>
<div class="campaign-review-layout"><section><a href="<?= $h($url(['view'=>'campaign','id'=>$id])) ?>">← Email checklist</a><h2><?= $h($draft['subject']??$campaign['name']) ?></h2><p><?= $h($draft['preview_text']??'') ?></p><?php if(!empty($draft['design'])): ?><iframe title="Team email preview" sandbox="" class="campaign-email-frame" data-email-preview="<?= $h(audienceDesignPreviewHtml($draft['design'],contentSecurityPolicyNonce(),null,false,$previewIdentity)) ?>"></iframe><?php else: ?><pre><?= $h($draft['text']??'No content yet.') ?></pre><?php endif; ?></section><aside><h2>Comments</h2><?php foreach($campaignComments as$comment): ?><article class="campaign-review-comment"><strong><?= $h($comment['actor_label']) ?></strong><time><?= $h(formatUserTimestamp($comment['created_at'],'Y-m-d H:i:s')) ?></time><p><?= nl2br($h($comment['body'])) ?></p><?php if($comment['resolved']): ?><small>Resolved</small><?php endif; ?></article><?php endforeach; ?><?php if(!$campaignComments): ?><p>No comments yet.</p><?php endif; ?><?php if($canManage&&$campaign['status']==='draft'): ?><form method="post"><?= $csrf ?><?php audienceInputs(['action'=>'campaign_comment','id'=>$id]); ?><label>Add a comment<textarea name="body" maxlength="4000" required><?= ($campaignRecovery['action']??'')==='campaign_comment'?$h(is_scalar($campaignRecovery['body']??null)?$campaignRecovery['body']:''):'' ?></textarea></label><button class="primary">Add comment</button></form><?php endif; ?></aside></div>
